package org.apache.commons.cli2.commandline;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Properties;
import java.util.Set;
import org.apache.commons.cli2.Argument;
import org.apache.commons.cli2.Option;
import org.apache.commons.cli2.WriteableCommandLine;
import org.apache.commons.cli2.option.PropertyOption;
import org.apache.commons.cli2.resource.ResourceConstants;
import org.apache.commons.cli2.resource.ResourceHelper;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class WriteableCommandLineImpl_getValues_TriageGen0Test {

    private WriteableCommandLineImpl commandLine;

    @Before
    public void setUp() {
        Option rootOption = new Option("root");
        commandLine = new WriteableCommandLineImpl(rootOption, new ArrayList<>());
    }

    @Test
    public void testGetValuesWithNoOption() {
        List<String> defaultValues = Collections.singletonList("default");
        List<String> result = commandLine.getValues(null, defaultValues);
        assertEquals(defaultValues, result);
    }

    @Test
    public void testGetValuesWithNullOption() {
        List<String> defaultValues = Collections.singletonList("default");
        List<String> result = commandLine.getValues(null, defaultValues);
        assertEquals(defaultValues, result);
    }

    @Test
    public void testGetValuesWithEmptyValueList() {
        Option option = new Option("opt");
        commandLine.setDefaultValues(option, Collections.emptyList());
        List<String> defaultValues = Collections.singletonList("default");
        List<String> result = commandLine.getValues(option, defaultValues);
        assertEquals(defaultValues, result);
    }

    @Test
    public void testGetValuesWithNonEmptyValueList() {
        Option option = new Option("opt");
        List<String> values = Collections.singletonList("value");
        commandLine.setDefaultValues(option, values);
        List<String> result = commandLine.getValues(option, Collections.emptyList());
        assertEquals(values, result);
    }

    @Test
    public void testGetValuesWithNonEmptyValueListAndNonEmptyDefaults() {
        Option option = new Option("opt");
        List<String> values = Collections.singletonList("value");
        List<String> defaults = Collections.singletonList("default");
        commandLine.setDefaultValues(option, values);
        List<String> result = commandLine.getValues(option, defaults);
        assertEquals(values, result);
    }

    @Test
    public void testGetValuesWithNullAndEmptyValueList() {
        Option option = new Option("opt");
        commandLine.setDefaultValues(option, null);
        List<String> defaultValues = Collections.singletonList("default");
        List<String> result = commandLine.getValues(option, defaultValues);
        assertEquals(defaultValues, result);
    }

    @Test
    public void testGetValuesWhenDefaultValuesAreUsed() {
        Option option = new Option("opt");
        commandLine.setDefaultValues(option, Collections.emptyList());
        List<String> result = commandLine.getValues(option, Collections.emptyList());
        assertTrue(result.isEmpty());
    }

    @Test
    public void testGetValuesWithNullReturnValue() {
        Option option = new Option("opt");
        commandLine.setDefaultValues(option, null);
        List<String> result = commandLine.getValues(option, null);
        assertTrue(result.isEmpty());
    }
}
